/**
 * Attribution & Third-Party Notices — the inventory the Terms of Use
 * Copyright Policy (AR 25-1) requires: every class of third-party material the
 * site reproduces, who owns it, and the basis on which it is used.
 *
 * Software licence texts live in /THIRD-PARTY-NOTICES.txt (generated by
 * scripts/build-third-party-notices.mjs); this page is the human-readable map.
 * tests/attribution.test.ts checks that every vendored asset named here still
 * exists and that every shipped licence file is linked from here.
 *
 * Status meanings:
 *   notice   — licence/notice shipped with the site; nothing further owed
 *   nominative — third-party trademark shown only to identify the product it
 *                labels; no affiliation or endorsement implied
 *   pending  — reproduced third-party content whose permission record the
 *              System Owner still has to file (AR 25-1); listed so the gap is
 *              visible rather than hidden
 */

type Status = 'notice' | 'nominative' | 'pending'

interface Entry {
  what: string
  owner: string
  basis: string
  where: string
  status: Status
}

interface Section {
  title: string
  intro: string
  entries: Entry[]
}

